// packages/core/src/services/today.ts
function createTodayService(db, plans, checkins) {
  const getToday = (date3 = todayStr()) => {
    const all = db.prepare("SELECT * FROM todos").all().map(mapTodo);
    const isOverdue = (t) => t.status === "open" && t.due_date !== null && (t.due_date < date3 || date3 === todayStr() && t.due_date === date3 && t.is_overdue);
    const overdue_todos = all.filter(isOverdue);
    const due_today_todos = all.filter((t) => t.status === "open" && t.due_date === date3 && !isOverdue(t));
    const completed_today_todos = all.filter((t) => t.completed_at?.startsWith(date3));
    const todayItems = plans.itemsOnDate(date3);
    const todayCheckins = checkins.list({ from: date3, to: date3 });
    const calendar_events = db.prepare(
      `SELECT * FROM calendar_events WHERE date <= ? AND COALESCE(end_date, date) >= ?
         ORDER BY date ASC, (start_time IS NULL) DESC, start_time ASC, id ASC`
    ).all(date3, date3).map(mapCalendarEvent);
    const summary = {
      todo_done_count: completed_today_todos.length,
      plan_item_done_count: todayItems.filter((i) => i.status === "done").length,
      manual_checkin_count: todayCheckins.filter((c) => c.ref_type === "day").length
    };
    const WEEK = ["\u65E5", "\u4E00", "\u4E8C", "\u4E09", "\u56DB", "\u4E94", "\u516D"];
    const [y, m, d] = date3.split("-").map(Number);
    const week = WEEK[new Date(y, m - 1, d).getDay()];
    const parts = [
      `${date3}\uFF08\u5468${week}\uFF09`,
      overdue_todos.length ? `${overdue_todos.length} \u9879\u5F85\u529E\u5DF2\u903E\u671F` : null,
      due_today_todos.length ? `${due_today_todos.length} \u9879\u4ECA\u5929\u5230\u671F` : null,
      calendar_events.length ? `\u65E5\u7A0B ${calendar_events.length} \u9879` : null,
      todayItems.length ? `\u5B66\u4E60\u5B89\u6392 ${todayItems.length} \u9879\uFF08\u5DF2\u5B8C\u6210 ${summary.plan_item_done_count}\uFF09` : "\u4ECA\u65E5\u65E0\u5B66\u4E60\u5B89\u6392",
      `\u4ECA\u65E5\u5B8C\u6210\u5F85\u529E ${summary.todo_done_count} \u9879\u3001\u6253\u5361 ${todayCheckins.length} \u6B21`,
      `\u5DF2\u8FDE\u7EED\u6253\u5361 ${checkins.streak()} \u5929`
    ].filter(Boolean);
    return {
      date: date3,
      overdue_todos,
      due_today_todos,
      completed_today_todos,
      today_plan_items: todayItems,
      checkins: todayCheckins,
      streak: checkins.streak(),
      summary,
      summary_text: parts.join("\uFF1B") + "\u3002",
      calendar_events
    };
  };
  return { getToday };
}

